class Solution:
    def first_positive(self, nums: list[int]) -> int:
        answer = None
        for value in nums:
            if value > 0:
                answer = value
                break
        return -1 if answer is None else answer

02-Java数组.md.template:
def compact_nonzero(nums: list[int]) -> None:
    write = 0
    for value in nums:
        if value != 0:
            nums[write] = value
            write += 1
    while write < len(nums):
        nums[write] = 0
        write += 1

